(()=>{const rail=document.getElementById('categories');document.querySelectorAll('[data-slide]').forEach(b=>b.addEventListener('click',()=>rail.scrollBy({left:Number(b.dataset.slide)*Math.max(180,rail.clientWidth*.75),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})));rail.addEventListener('focusin',e=>e.target.closest('[data-cat]')?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'instant'}));})();